// === Tab: mySketch ===
// Simplex noiseを用いてデザイン
// https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83

// hsb2rgbの関数：https://thebookofshaders.com/06/?lan=jp（The Book of Shaders:color）

// はぅ君のスケッチ(BreezeFlow)を参考にして作ってみた
// 参考：https://github.com/haukun/Processing/blob/master/BreezeFlow/BreezeFlow/BreezeFlow.pde
// "若干" アレンジしてみました

// 調和平均で書き直し。幾何平均と違って、1つの変数が0に近い時にその変数に値が近くなるので。
// 幾何平均だと問答無用で0に近くなってしまうのでこっちの方がよいかと（分かんないけどね）
// ならないや。3倍・・まあ細かいことはいいよね。一応、平均だし。

'use strict';

let myShader;
let properFrameCount;
let isLoop = true;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"const float PI = 3.14159;" +
"uniform float fc;" +
"uniform vec2 resolution;" +
"float scaled_cosine(float x){ return 0.5 * (1.0 + cos(x * PI)); }" +
"vec4 permute(vec4 x){return mod(((x*34.0)+1.0)*x, 289.0);}" +
"vec4 taylorInvSqrt(vec4 r){return 1.79284 - 0.85373 * r;}" +
"float snoise(vec3 v){" +
"  const vec2  C = vec2(1.0/6.0, 1.0/3.0);" +
"  const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);" +
"  vec3 i = floor(v + dot(v, C.yyy) );" +
"  vec3 x0 = v - i + dot(i, C.xxx) ;" +
"  vec3 g = step(x0.yzx, x0.xyz);" +
"  vec3 l = 1.0 - g;" +
"  vec3 i1 = min( g.xyz, l.zxy );" +
"  vec3 i2 = max( g.xyz, l.zxy );" +
"  vec3 x1 = x0 - i1 + 1.0 * C.xxx;" +
"  vec3 x2 = x0 - i2 + 2.0 * C.xxx;" +
"  vec3 x3 = x0 - 1. + 3.0 * C.xxx;" +
"  i = mod(i, 289.0 );" +
"  vec4 p = permute( permute( permute(" + 
"             i.z + vec4(0.0, i1.z, i2.z, 1.0 ))" +
"           + i.y + vec4(0.0, i1.y, i2.y, 1.0 ))" + 
"           + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));" +
"  float n_ = 1.0/7.0;" +
"  vec3  ns = n_ * D.wyz - D.xzx;" +
"  vec4 j = p - 49.0 * floor(p * ns.z *ns.z);" +
"  vec4 x_ = floor(j * ns.z);" +
"  vec4 y_ = floor(j - 7.0 * x_ );" +
"  vec4 x = x_ *ns.x + ns.yyyy;" +
"  vec4 y = y_ *ns.x + ns.yyyy;" +
"  vec4 h = 1.0 - abs(x) - abs(y);" +
"  vec4 b0 = vec4( x.xy, y.xy );" +
"  vec4 b1 = vec4( x.zw, y.zw );" +
"  vec4 s0 = floor(b0)*2.0 + 1.0;" +
"  vec4 s1 = floor(b1)*2.0 + 1.0;" +
"  vec4 sh = -step(h, vec4(0.0));" +
"  vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy;" +
"  vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww;" +
"  vec3 p0 = vec3(a0.xy,h.x);" +
"  vec3 p1 = vec3(a0.zw,h.y);" +
"  vec3 p2 = vec3(a1.xy,h.z);" +
"  vec3 p3 = vec3(a1.zw,h.w);" +
"  vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));" +
"  p0 *= norm.x;" +
"  p1 *= norm.y;" +
"  p2 *= norm.z;" +
"  p3 *= norm.w;" +
"  vec4 m = max(0.6 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);" +
"  m = m * m;" +
"  return 42.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1)," +
"                                dot(p2,x2), dot(p3,x3)));" +
"}" +
"vec3 hsb2rgb(vec3 c){" +
"    vec3 rgb = clamp(abs(mod(c.x*6.0+vec3(0.0,4.0,2.0)," +
"                             6.0)-3.0)-1.0," +
"                     0.0," +
"                     1.0 );" +
"    rgb = rgb*rgb*(3.0-2.0*rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
"float harmonic(float a, float b, float c){" +
"  return (a * b * c * 3.0) / (a * b + b * c + c * a);" +
"}" +
"float geometric(float a, float b, float c){" +
"  return pow(a * b * c, 0.7);" +
"}" +
"void main(){" +
"  float t = fc * 0.009;" +
"  vec2 pole0 = resolution.xy * 0.9;" +
"  float radius = 1.1 * min(resolution.x, resolution.y);" +
"  vec2 pole3 = pole0 + radius * vec2(cos(t * 0.2), sin(t * 2.0));" +
"  vec2 pole4 = pole0 + radius * vec2(cos(t * 0.4 + PI * 1.0 / 3.0), sin(t * 2.0 + PI * 2.0 / 3.0));" +
"  vec2 pole5 = pole0 + radius * vec2(cos(t * 0.6 + PI * 3.0 / 3.0), sin(t * 2.0 + PI * 4.0 / 3.0));" +
"  vec2 v3 = gl_FragCoord.xy - pole3;" +
"  vec2 v4 = gl_FragCoord.xy - pole4;" +
"  vec2 v5 = gl_FragCoord.xy - pole5;" +
"  float d3 = harmonic(length(v3), length(v4), length(v5)) * 0.005;" +
"  float a2 = (atan(v3.y, v3.x) + atan(v4.y, v4.x) + atan(v5.y, v5.x)) * 0.666;" +
"  float factor = scaled_cosine(sin(sin(d3 + t) * d3 + 10.5 * (a2 + t * 2.0)));" +
"  float c = abs(tan(scaled_cosine(snoise(vec3(d3, factor, t))) * 2.0 * PI));" +
"  vec3 v9 = hsb2rgb(vec3(mod((100.0 * d3 + 100.0 * t + 30.5  + (10.0 * sin(2.0 * a2))), 255.0) / 255.0, 1.0 - c, c));" +
"  gl_FragColor = vec4(v9, 1.0);" +
"}";
/*
"  float factor = scaled_cosine(sin(sin(d + t) * d + 7.5 * (a + t * 2.0)));" +
"  float c = abs(tan(scaled_cosine(snoise(vec3(d, factor, t))) * 2.0 * PI));" +
"  vec3 v9 = hsb2rgb(vec3(mod((100.0 * d + 100.0 * t + 40.5 * a), 255.0) / 255.0, 1.0 - c, c));" +

bipole:
"  vec2 pole1 = pole0 + radius * vec2(cos(t * 1.0), sin(t * 2.0));" +
"  vec2 pole2 = pole0 + radius * vec2(-cos(t * 2.0), -sin(t * 2.0));" +

"  vec2 v1 = gl_FragCoord.xy - pole1;" +
"  vec2 v2 = gl_FragCoord.xy - pole2;" +

"  float d2 = sqrt(length(v1) * length(v2)) * 0.006;" +
"  float a1 = (atan(v1.y, v1.x) + atan(v2.y, v2.x)) * 0.65;" +

"  float factor = scaled_cosine(sin(sin(d2 + t) * d2 + 7.0 * (a1 + t * 2.0)));" +
"  float c = abs(tan(scaled_cosine(snoise(vec3(d2, factor, t))) * 2.0 * PI));" +
"  vec3 v9 = hsb2rgb(vec3(mod((50.0 * d2 + 100.0 * t + 30.5  + (10.0 * sin(1.0 * a1))), 255.0) / 255.0, 1.0 - c, c));" +
*/
// factor部分を2乗して3.5でも切れ目が出ないように改造したら切れ目が消えたので良き良き
// a部分をいじって回転させたりして

function setup(){
  createCanvas(1666, 1666, WEBGL);
  colorMode(HSB, 255);
  noStroke();
  myShader = createShader(vs, fs);
  shader(myShader);
  //noLoop();
	properFrameCount = 0;
}

function draw(){
  background(70, 30, 100);
	myShader.setUniform("fc", properFrameCount);
	myShader.setUniform("resolution", [width, height]);
  quad(-1.0, -1.0, 2.0, -1.0, 1.0, 2.0, -1.0, 1.0);
	properFrameCount++;
}

function keyTyped(){
	if(key === 'p'){
		if(isLoop){ isLoop = false; noLoop(); }
		else{ isLoop = true; loop(); }
	}
}

